// Ein Beispiel-Gespräch, damit du die Vorlage sofort testen kannst.
// Später kommt das echte Gespräch über "Gespräch kommt rein" (links oben).
return [{
  json: {
    kunde: 'Physiopraxis am Park',
    transkript: `Agentur: Schön, dass es losgeht. Lass uns kurz durchgehen, was ihr euch wünscht.
Kunde: Wichtigstes Thema ist Instagram. Wir posten gerade gar nicht, wollen aber ab nächsten Monat drei Mal die Woche etwas zeigen. Vor allem Übungen und das Team.
Agentur: Gibt es schon Fotos vom Team?
Kunde: Nein, die bräuchten wir. Ein Fotograf wäre super, gern noch diesen Monat.
Agentur: Okay. Und die Website?
Kunde: Die ist alt. Die Online-Terminbuchung soll prominenter werden, und die Leistungsseiten sind veraltet. Die Texte schicke ich euch bis Freitag.
Kunde: Außerdem wollen wir Google Ads für "Physiotherapie Köln" testen, Budget so 500 Euro im Monat.
Agentur: Dann brauchen wir Zugang zu eurem Google-Konto und zur Website.
Kunde: Die Zugänge schicke ich heute noch. Unser Logo gibt es nur als JPG, ist das schlimm?
Agentur: Wir bauen es als Vektor nach. Nächster Termin: Kick-off mit dem ganzen Team in zwei Wochen?
Kunde: Passt, am liebsten dienstags.`,
  },
}];

// ================= EINSTELLUNGEN =================

// TESTMODUS: true  = läuft ohne Zugänge mit einer Beispiel-Antwort der KI
//                    und zeigt am Ende nur eine Vorschau der Aufgaben.
//            false = echte KI (OpenAI) + Aufgaben werden in ClickUp angelegt.
const TESTMODUS = true;

// ClickUp-Liste, in der die Aufgaben landen sollen.
// Die ID steht in der Adresse der Liste: app.clickup.com/.../v/li/<LIST-ID>
const CLICKUP_LIST_ID = 'HIER-LIST-ID-EINTRAGEN';

// Dein Team:
// rolle:      so heißt die Rolle in deiner Agentur
// name:       wer die Aufgaben bekommt
// zustaendig: wofür die Person zuständig ist (daran erkennt die KI, wer was bekommt)
// clickupId:  ClickUp-User-ID, damit die Aufgabe der Person zugewiesen wird
//             (optional; leer lassen = Aufgabe ohne Zuweisung, Name steht im Titel)
const TEAM = [
  { rolle: 'Projektleitung', name: 'Lisa',  clickupId: '', zustaendig: 'Kick-off, Termine, Zugänge, Abstimmung mit dem Kunden, Angebote' },
  { rolle: 'Design',         name: 'Tom',   clickupId: '', zustaendig: 'Logo, Moodboards, Layouts, Grafiken, Fotos, Webdesign' },
  { rolle: 'Content',        name: 'Mia',   clickupId: '', zustaendig: 'Texte, Redaktionsplan, Social Media, Blog, Website-Texte' },
  { rolle: 'Ads',            name: 'Jonas', clickupId: '', zustaendig: 'Google Ads, Meta Ads, Tracking, Budgets, Reporting' },
];

const STANDARD_ROLLE = 'Projektleitung'; // bekommt alles, was die KI nicht zuordnen kann
// ==================================================

const d = $input.first().json;
const quelle = d.body || d; // vom Webhook kommt alles in "body"
return [{
  json: {
    testmodus: TESTMODUS,
    clickupListId: CLICKUP_LIST_ID,
    kunde: String(quelle.kunde || 'Neuer Kunde'),
    transkript: String(quelle.transkript || ''),
    team: TEAM,
    standardRolle: STANDARD_ROLLE,
  },
}];

// So sieht eine typische Antwort der KI zum Beispiel-Gespräch aus.
// Wird nur im TESTMODUS genutzt, damit du ohne OpenAI-Zugang testen kannst.
const aufgaben = [
  { titel: 'Zugänge zu Google-Konto und Website nachhalten', beschreibung: 'Kunde wollte die Zugänge heute schicken. Eingang prüfen, sonst nachfragen.', rolle: 'Projektleitung', prioritaet: 'hoch', faellig_in_tagen: 1, aus_dem_gespraech: 'Die Zugänge schicke ich heute noch' },
  { titel: 'Fotografen für Teamfotos buchen', beschreibung: 'Shooting für Team- und Übungsfotos noch in diesem Monat organisieren.', rolle: 'Projektleitung', prioritaet: 'hoch', faellig_in_tagen: 4, aus_dem_gespraech: 'Ein Fotograf wäre super, gern noch diesen Monat' },
  { titel: 'Website-Texte vom Kunden nachhalten', beschreibung: 'Texte für die Leistungsseiten sind bis Freitag zugesagt.', rolle: 'Projektleitung', prioritaet: 'mittel', faellig_in_tagen: 3, aus_dem_gespraech: 'Die Texte schicke ich euch bis Freitag' },
  { titel: 'Kick-off mit dem ganzen Team planen', beschreibung: 'Termin in zwei Wochen, möglichst an einem Dienstag.', rolle: 'Projektleitung', prioritaet: 'mittel', faellig_in_tagen: 3, aus_dem_gespraech: 'Kick-off in zwei Wochen, am liebsten dienstags' },
  { titel: 'Logo als Vektor nachbauen', beschreibung: 'Logo liegt nur als JPG vor, sauber als Vektor nachbauen.', rolle: 'Design', prioritaet: 'mittel', faellig_in_tagen: 5, aus_dem_gespraech: 'Logo gibt es nur als JPG' },
  { titel: 'Online-Terminbuchung prominenter platzieren', beschreibung: 'Terminbuchung auf der Startseite und den Leistungsseiten deutlich sichtbar machen.', rolle: 'Design', prioritaet: 'mittel', faellig_in_tagen: 8, aus_dem_gespraech: 'Online-Terminbuchung soll prominenter werden' },
  { titel: 'Redaktionsplan für Instagram erstellen', beschreibung: 'Drei Posts pro Woche ab nächstem Monat, Schwerpunkt Übungen und Team.', rolle: 'Content', prioritaet: 'hoch', faellig_in_tagen: 6, aus_dem_gespraech: 'ab nächsten Monat drei Mal die Woche' },
  { titel: 'Leistungsseiten der Website überarbeiten', beschreibung: 'Veraltete Leistungsseiten mit den neuen Texten des Kunden aktualisieren.', rolle: 'Content', prioritaet: 'mittel', faellig_in_tagen: 8, aus_dem_gespraech: 'Leistungsseiten sind veraltet' },
  { titel: 'Google-Ads-Kampagne „Physiotherapie Köln“ aufsetzen', beschreibung: 'Testkampagne mit rund 500 € Monatsbudget, sobald die Zugänge da sind.', rolle: 'Ads', prioritaet: 'mittel', faellig_in_tagen: 7, aus_dem_gespraech: 'Budget so 500 Euro im Monat' },
];
return [{ json: { choices: [{ message: { content: JSON.stringify({ aufgaben }) } }] } }];

// Baut die Anfrage an die KI. Hier musst du normalerweise nichts ändern.
const d = $input.first().json;
const rollen = d.team.map(t => `- ${t.rolle}: ${t.zustaendig}`).join('\n');

const system = `Du bist Projektassistenz in einer Marketing-Agentur.
Du bekommst das Transkript eines Onboarding-Gesprächs mit einem neuen Kunden.
Finde jede konkrete Aufgabe, die die Agentur nach dem Gespräch erledigen muss, und ordne sie genau einer Rolle zu.

Rollen im Team:
${rollen}

Regeln:
- Nur echte To-dos der Agentur, keine Aufgaben des Kunden. Wenn der Kunde etwas liefern muss, wird daraus eine Aufgabe "nachhalten" für die Projektleitung.
- Titel kurz und als Tätigkeit formuliert (z. B. "Moodboard für Instagram erstellen").
- rolle muss exakt einer der Rollen oben entsprechen. Wenn unklar: "${d.standardRolle}".
- faellig_in_tagen: realistische Anzahl Arbeitstage ab heute, Zeitangaben aus dem Gespräch beachten.
- prioritaet: "hoch", "mittel" oder "niedrig".
- aus_dem_gespraech: die Stelle aus dem Gespräch in wenigen Worten, damit klar ist, woher die Aufgabe kommt.

Antworte nur mit JSON in diesem Format:
{"aufgaben":[{"titel":"","beschreibung":"","rolle":"","prioritaet":"","faellig_in_tagen":0,"aus_dem_gespraech":""}]}`;

return [{
  json: {
    model: 'gpt-4o-mini',
    temperature: 0.2,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: `Kunde: ${d.kunde}\n\nTranskript:\n${d.transkript}` },
    ],
  },
}];

// Nimmt die Aufgaben der KI und macht daraus fertige Aufgaben
// mit zuständiger Person, Fälligkeit und Priorität (eine Aufgabe pro Zeile).
const ctx = $('Team & Einstellungen').first().json;
let aufgaben = [];
try {
  aufgaben = JSON.parse($input.first().json.choices[0].message.content).aufgaben || [];
} catch (e) {
  throw new Error('Die KI hat kein gültiges JSON geliefert: ' + e.message);
}

const team = ctx.team;
const standard = team.find(t => t.rolle === ctx.standardRolle) || team[0];
const finde = rolle => team.find(t => t.rolle.toLowerCase() === String(rolle || '').toLowerCase()) || standard;

// Fälligkeit in Arbeitstagen (Wochenenden werden übersprungen)
const faellig = tage => {
  const d = new Date();
  let n = Math.max(1, Number(tage) || 3);
  while (n > 0) { d.setDate(d.getDate() + 1); if (d.getDay() !== 0 && d.getDay() !== 6) n--; }
  d.setHours(17, 0, 0, 0);
  return d;
};
// ClickUp-Priorität: 1 = dringend, 2 = hoch, 3 = normal, 4 = niedrig
const prio = { hoch: 2, mittel: 3, niedrig: 4 };

return aufgaben.map(a => {
  const p = finde(a.rolle);
  const datum = faellig(a.faellig_in_tagen);
  return {
    json: {
      aufgabe: `${a.titel} (${p.name})`,
      kunde: ctx.kunde,
      zustaendig: p.name,
      rolle: p.rolle,
      faellig: datum.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit' }),
      prioritaet: a.prioritaet || 'mittel',
      aus_dem_gespraech: a.aus_dem_gespraech || '',
      // fertige Felder für das Projekt-Tool:
      titel: `[${ctx.kunde}] ${a.titel}`,
      beschreibung: `${a.beschreibung || ''}\n\n**Zuständig:** ${p.name} (${p.rolle})\n**Aus dem Onboarding-Gespräch:** „${a.aus_dem_gespraech || '-'}“`,
      faelligMs: datum.getTime(),
      prioritaetClickup: prio[a.prioritaet] || 3,
      clickupId: p.clickupId || '',
    },
  };
});
